<script setup lang="ts">
import { computed, reactive, ref, toRaw } from 'vue';
import { message } from 'ant-design-vue';
import { api } from '../services/api';
import type { CatalogSummary, RoleConfiguration, RoleTemplate, RoleTemplateVersion, ResourceOwnerType } from '../types';
import type { OwnershipOption } from '../composables/ownership';
import OwnershipFields from '../components/OwnershipFields.vue';
import { rolePresets } from './rolePresets';
const props = defineProps<{ catalog?: CatalogSummary; currentUserId:string; ownershipOptions:OwnershipOption[] }>();
const emit = defineEmits<{refreshCatalog:[]}>();
const activeId = ref(''); const modal = ref(false); const saving = ref(false); const metadataOnly = ref(false); const target = ref<RoleTemplate|null>(null);
const selected = computed(() => props.catalog?.roleTemplates.find(item => item.id === activeId.value) ?? props.catalog?.roleTemplates[0]);
const form = reactive({ name:'', description:'', ownerType:'PERSON' as ResourceOwnerType, ownerId:'', status:'DRAFT' as 'DRAFT'|'PUBLISHED', configuration:blankConfiguration() });
function blankConfiguration():RoleConfiguration { return { role:'', responsibility:'', systemPrompt:'', modelVersionId:null, privacyModelVersionId:null, privacyMappingEnabled:false, knowledgeReleaseId:null, memoryWindowSize:40, skillVersionIds:[], toolVersionIds:[], playbookVersionIds:[] }; }
function resources(type:string) { return (props.catalog?.resources ?? []).filter(item => item.type === type).flatMap(item => item.versions.filter(version => version.status === 'PUBLISHED').map(version => ({label:`${item.name} · ${version.version}`, value:version.id}))); }
const models = computed(() => resources('LLM_MODEL'));
const privateModels = computed(() => props.catalog?.resources.filter(item=>item.type==='LLM_MODEL').flatMap(item=>item.versions.filter(version=>version.status==='PUBLISHED' && version.configuration.llmModel?.privateDeployment).map(version=>({label:`${item.name} · ${version.version}`,value:version.id}))) ?? []); const tools = computed(() => resources('TOOL')); const skills = computed(() => resources('SKILL'));
const knowledge = computed(() => props.catalog?.knowledgeBases.flatMap(item => item.releases.filter(v => v.status === 'PUBLISHED').map(v => ({label:`${item.name} · ${v.version}`, value:v.id}))) ?? []);
const playbooks = computed(() => props.catalog?.playbooks.flatMap(item => item.versions.filter(v => v.status === 'PUBLISHED').map(v => ({label:`${item.name} · ${v.version}`, value:v.id}))) ?? []);
function open(template?:RoleTemplate, metadata=false, version?:RoleTemplateVersion) { target.value=template??null; metadataOnly.value=metadata; Object.assign(form,{name:template?.name??'', description:template?.description??'',ownerType:template?.ownerType??'PERSON',ownerId:template?.ownerId??props.currentUserId,status:'DRAFT',configuration:structuredClone(toRaw(version?.configuration??template?.latestVersion?.configuration??blankConfiguration()))}); modal.value=true; }
function preset(key:string) { const value=rolePresets.find(item=>item.key===key); if(value) { form.name=value.name; form.description=value.responsibility; Object.assign(form.configuration,{role:value.role,responsibility:value.responsibility,systemPrompt:value.systemPrompt}); } }
async function save() { if(!form.name.trim() || !form.ownerId) return void message.error('请填写名称与归属。'); if(!metadataOnly.value && form.status==='PUBLISHED' && !form.configuration.modelVersionId) return void message.error('发布前请选择已发布的模型版本。'); saving.value=true; try { const metadata={name:form.name,description:form.description,ownerType:form.ownerType,ownerId:form.ownerId}; const version={status:form.status,configuration:form.configuration}; if(!target.value) {const result=await api.createRoleTemplate({...metadata,initialVersion:version});activeId.value=result.id;} else if(metadataOnly.value) await api.updateRoleTemplate(target.value.id,metadata); else await api.createRoleTemplateVersion(target.value.id,version); modal.value=false; emit('refreshCatalog'); void message.success('角色模板已保存'); } catch(e) {void message.error(e instanceof Error?e.message:String(e));} finally {saving.value=false;} }
async function publish(version:RoleTemplateVersion) { try {await api.publishRoleTemplateVersion(version.templateId,version.id);emit('refreshCatalog');void message.success('版本已发布');}catch(e){void message.error(e instanceof Error?e.message:String(e));} }
async function remove(template:RoleTemplate) {try {await api.deleteRoleTemplate(template.id);emit('refreshCatalog');}catch(e){void message.error(e instanceof Error?e.message:String(e));}}
</script>
<template>
  <a-card title="角色模板"><template #extra><a-button type="primary" @click="open()">创建角色模板</a-button></template>
    <a-alert type="info" show-icon message="模板提供上下文与能力配置，实际执行权限由入口和授权决定。已发布版本可持续被实例引用。" style="margin-bottom:20px" />
    <a-alert v-if="!models.length" type="warning" show-icon message="先配置真实模型，再发布接待角色。" style="margin-bottom:20px"><template #description><router-link to="/console/resources">打开资源库，创建并发布模型版本</router-link></template></a-alert>
    <a-empty v-if="!catalog?.roleTemplates.length" description="从接待、执行或审阅预设开始，按实际工作调整提示词。" />
    <div v-else class="role-grid"><a-menu :selected-keys="selected?[selected.id]:[]" @click="(item: {key: string | number})=>activeId=String(item.key)"><a-menu-item v-for="item in catalog.roleTemplates" :key="item.id">{{item.name}}</a-menu-item></a-menu>
      <div v-if="selected"><a-space wrap><h2>{{selected.name}}</h2><a-button @click="open(selected,true)">编辑基本信息</a-button><a-button type="primary" @click="open(selected)">创建新版本</a-button><a-popconfirm title="删除此模板？已有发布版本将被保护。" @confirm="remove(selected)"><a-button danger>删除</a-button></a-popconfirm></a-space><p>{{selected.description}}</p>
        <a-collapse><a-collapse-panel v-for="version in selected.versions" :key="version.id" :header="`${version.version} · ${version.status==='PUBLISHED'?'已发布':'草稿'}`"><a-descriptions :column="1"><a-descriptions-item label="角色">{{version.configuration.role}}</a-descriptions-item><a-descriptions-item label="职责">{{version.configuration.responsibility}}</a-descriptions-item><a-descriptions-item label="模型版本">{{models.find(item=>item.value===version.configuration.modelVersionId)?.label??'尚未配置'}}</a-descriptions-item><a-descriptions-item label="工具 / Skill / Playbook">{{version.configuration.toolVersionIds.length}} / {{version.configuration.skillVersionIds.length}} / {{version.configuration.playbookVersionIds.length}}</a-descriptions-item></a-descriptions><pre class="prompt">{{version.configuration.systemPrompt}}</pre><a-space><a-button @click="open(selected,false,version)">以此创建新版本</a-button><a-button v-if="version.status==='DRAFT'" type="primary" @click="publish(version)">发布此版本</a-button></a-space></a-collapse-panel></a-collapse>
      </div></div>
  </a-card>
  <a-modal v-model:open="modal" :title="metadataOnly?'编辑角色信息':target?'创建角色版本':'创建角色模板'" width="850px" :confirm-loading="saving" @ok="save">
    <a-form layout="vertical"><template v-if="!target || metadataOnly"><a-form-item v-if="!target" label="预制上下文"><a-space><a-button v-for="item in rolePresets" :key="item.key" @click="preset(item.key)">{{item.name}}</a-button></a-space></a-form-item><a-form-item label="名称" required><a-input v-model:value="form.name" /></a-form-item><a-form-item label="描述"><a-textarea v-model:value="form.description" /></a-form-item><OwnershipFields v-model:owner-type="form.ownerType" v-model:owner-id="form.ownerId" :options="ownershipOptions" /></template>
    <template v-if="!metadataOnly"><a-form-item label="角色"><a-input v-model:value="form.configuration.role" /></a-form-item><a-form-item label="职责"><a-textarea v-model:value="form.configuration.responsibility" /></a-form-item><a-form-item label="系统提示词"><a-textarea v-model:value="form.configuration.systemPrompt" :rows="9" /></a-form-item><a-form-item label="模型版本" :required="form.status==='PUBLISHED'"><a-select v-model:value="form.configuration.modelVersionId" :options="models" show-search option-filter-prop="label" allow-clear /></a-form-item><a-form-item label="保留近期消息数"><a-input-number v-model:value="form.configuration.memoryWindowSize" :min="1" :max="1000" /></a-form-item><a-form-item label="知识版本"><a-select v-model:value="form.configuration.knowledgeReleaseId" :options="knowledge" allow-clear /></a-form-item><a-form-item label="工具版本"><a-select v-model:value="form.configuration.toolVersionIds" mode="multiple" :options="tools" /></a-form-item><a-form-item label="Skill 版本"><a-select v-model:value="form.configuration.skillVersionIds" mode="multiple" :options="skills" /></a-form-item><a-form-item label="Playbook 版本"><a-select v-model:value="form.configuration.playbookVersionIds" mode="multiple" :options="playbooks" /></a-form-item><a-form-item label="隐私映射"><a-switch v-model:checked="form.configuration.privacyMappingEnabled" /></a-form-item><a-form-item v-if="form.configuration.privacyMappingEnabled" label="私有模型版本"><a-select v-model:value="form.configuration.privacyModelVersionId" :options="privateModels" allow-clear /></a-form-item><a-form-item label="保存状态"><a-radio-group v-model:value="form.status"><a-radio value="DRAFT">草稿</a-radio><a-radio value="PUBLISHED">发布</a-radio></a-radio-group></a-form-item></template></a-form>
  </a-modal>
</template>
<style scoped>.role-grid{display:grid;grid-template-columns:220px minmax(0,1fr);gap:28px}.prompt{white-space:pre-wrap;line-height:1.8;background:#f7f8fa;padding:18px;border-radius:8px}@media(max-width:850px){.role-grid{grid-template-columns:1fr}}</style>
